<?php
declare(strict_types=1);
// Authenticated dashboard/workspace rendering is the cron safety-net opportunity.
task_notification_authenticated_fallback(get_db(), current_user());
$notificationPoll=task_notification_config()['poll_seconds'];$notificationCsrf=csrf_token();
?><a class="notification-bell" href="notifications.php" data-notification-bell aria-label="Notifications, no unread notifications"><span aria-hidden="true">🔔</span><span class="notification-badge" data-notification-count hidden>0</span><span class="sr-only">Notifications</span></a>
<style>.notification-bell{position:relative;display:inline-flex;align-items:center;justify-content:center;min-width:44px;min-height:44px;border-radius:999px;text-decoration:none;background:#fff;color:#172033;border:1px solid #cbd5e1}.notification-badge{position:absolute;top:-5px;right:-7px;min-width:20px;padding:2px 5px;border-radius:99px;background:#b42318;color:#fff;border:2px solid #fff;font:700 11px/16px system-ui;text-align:center}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:420px){.notification-bell{flex:0 0 44px;margin:4px}}</style>
<script>(function(){if(window.TaskNotifications)return;let running=false,timer;const endpoint='api/notifications.php?action=count',csrf=<?=json_encode($notificationCsrf)?>,interval=<?=$notificationPoll*1000?>;function paint(n){document.querySelectorAll('[data-notification-bell]').forEach(b=>{const c=b.querySelector('[data-notification-count]'),text=n>99?'99+':String(n);c.textContent=text;c.hidden=n===0;b.setAttribute('aria-label',n===0?'Notifications, no unread notifications':n+' unread notification'+(n===1?'':'s'));});}async function refresh(){if(running||document.hidden)return;running=true;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),8000);try{const r=await fetch(endpoint,{headers:{'X-CSRF-Token':csrf,'Accept':'application/json'},credentials:'same-origin',cache:'no-store',signal:controller.signal});if(r.ok){const j=await r.json();if(j.ok)paint(Number(j.data.unread_count)||0);}}catch(e){}finally{clearTimeout(timeout);running=false;}}function schedule(){clearInterval(timer);timer=undefined;if(!document.hidden)timer=setInterval(refresh,interval);}document.addEventListener('visibilitychange',()=>{schedule();if(!document.hidden)refresh();});document.addEventListener('task-notifications:refresh',refresh);window.TaskNotifications={refresh,paint};schedule();refresh();})();</script>
